import java.io.*;import com.jpexs.decompiler.flash.SWF;class PrintSocialInit{public static void main(String[]args)throws Exception{var s=new SWF(new FileInputStream(args[0]),true);for(var p:s.getAS3Packs())if(p.getClassPath().toString().equals("SocialMarriageBridge")){var a=p.abc;for(var info:a.script_info){System.out.println("script"+info.init_index);for(var x:a.findBody(info.init_index).getCode().code){System.out.print(x.definition.instructionName+" "+java.util.Arrays.toString(x.operands));if(x.operands!=null&&x.operands.length>0&&java.util.Set.of("initproperty","getlex","findpropstrict").contains(x.definition.instructionName))System.out.print(" "+a.constants.getString(a.constants.getMultiname(x.operands[0]).name_index));System.out.println();}}}}}
